import sys

def solve():
    # Read N from standard input
    try:
        input_data = sys.stdin.read().split()
    except Exception:
        return

    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        # Read the sequence A
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))
    except StopIteration:
        return

    # Check for the condition: A[i] == A[i+1] == A[i+2]
    found = False
    for i in range(n - 1):
        if a[i] == a[i+1] == a[i+2]:
            found = True
            break

    if found:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
